"use strict";
import { Flex, Text, styled as uiStyled } from "ui/src";
import { useVaultContext } from "../ContextProvider";
const Container = uiStyled(Flex, {
  mt: "$spacing24",
  flexDirection: "row",
  gap: "$gap24",
  borderBottomWidth: 1,
  borderBottomColor: "$surface3",
  // divider line
  width: "100%",
  paddingBottom: 0
});
const TabButton = uiStyled(Flex, {
  cursor: "pointer",
  paddingBottom: "$spacing12",
  marginBottom: -1,
  // overlap border
  borderBottomWidth: 2,
  borderBottomColor: "transparent",
  hoverStyle: {
    opacity: 0.8
  },
  variants: {
    active: {
      true: {
        borderBottomColor: "$neutral1"
      }
    }
  }
});
const TABS = ["Your position", "Overview", "Performance", "Risk", "Activity"];
export default function ActionBar() {
  const { activeTab, setActiveTab } = useVaultContext();
  return <Container>
      {TABS.map((tab) => {
    const isActive = activeTab === tab;
    return <TabButton key={tab} active={isActive} onPress={() => setActiveTab(tab)}>
            <Text variant="body2" color={isActive ? "$neutral1" : "$neutral2"}>
              {tab}
            </Text>
          </TabButton>;
  })}
    </Container>;
}
